from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base GESUMMV kernel.
# For each row i:
#   tmp[i] = A[i,*] · x
#   y[i]   = alpha * tmp[i] + beta * (B[i,*] · x)
#
# We use per-row scalar accumulators (tmp_i, y_i) so the inner loop
# operates purely on registers and touches memory only once per row.
@proc
def kernel_gesummv_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        tmp_i: DATA_TYPE
        y_i: DATA_TYPE

        tmp_i = 0.0
        y_i = 0.0

        for j in seq(0, n):
            tmp_i += A[i, j] * x[j]
            y_i += B[i, j] * x[j]

        tmp[i] = tmp_i
        y[i] = alpha * tmp_i + beta * y_i


# Start from the base kernel and apply schedule transformations.
kernel_gesummv = kernel_gesummv_base

# Tunable unrolling factor for the inner j-loop.
VEC = 8

# 1. Strip-mine the j loop: j -> (jo, ji) with a separate tail loop.
#    This creates a constant-bounded inner loop that we can unroll.
kernel_gesummv = divide_loop(kernel_gesummv, "j", VEC, ("jo", "ji"), tail="cut")

# 2. Unroll the main ji loop (the first occurrence) to expose ILP and
#    make it easier for the C compiler to auto-vectorize.
kernel_gesummv = unroll_loop(kernel_gesummv, "ji #0")

# 3. Parallelize the outer i loop with OpenMP. Each iteration works on
#    distinct tmp[i] and y[i], so there are no loop-carried dependences.
kernel_gesummv = parallelize_loop(kernel_gesummv, "i")

# 4. Clean up expressions and remove any dead code created by the schedule.
kernel_gesummv = simplify(kernel_gesummv)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


