from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Baseline GESUMMV kernel written in Exo object code.
# We keep tmp as an explicit output buffer for compatibility
# with the PolyBench interface, but accumulate into scalars
# to avoid redundant memory traffic inside the inner loop.
@proc
def kernel_gesummv_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    B: DATA_TYPE[n, n] @ DRAM,
    tmp: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
):
    for i in seq(0, n):
        # Per-row accumulators kept in registers
        tmp_i: DATA_TYPE
        y_i: DATA_TYPE

        tmp_i = 0.0
        y_i = 0.0

        for j in seq(0, n):
            # Load x[j] once per inner iteration to enable reuse
            t: DATA_TYPE
            t = x[j]
            tmp_i += A[i, j] * t
            y_i  += B[i, j] * t

        # Write back results once per row
        tmp[i] = tmp_i
        y[i] = alpha * tmp_i + beta * y_i

# ---------------------------------------------------------------------------
# Scheduling:
# 1. Tile the inner j-loop by a small constant factor (4) to expose a
#    fixed-size inner loop.
# 2. Fully unroll the 4-iteration tile loop to reduce loop overhead and
#    encourage the C compiler to vectorize.
# 3. Parallelize the outer i-loop with OpenMP; each iteration updates an
#    independent row of A, B, tmp, and y.
# 4. Simplify the final IR and rename it to the externally visible
#    kernel_gesummv used by the C driver.
# ---------------------------------------------------------------------------
kernel_gesummv_scheduled = divide_loop(kernel_gesummv_base, "j", 4, ("jo", "ji"), tail="guard")
kernel_gesummv_scheduled = unroll_loop(kernel_gesummv_scheduled, "ji")
kernel_gesummv_scheduled = parallelize_loop(kernel_gesummv_scheduled, "i")
kernel_gesummv = rename(simplify(kernel_gesummv_scheduled), "kernel_gesummv")
